action_details.action_postfix:
0.0 /in_additions xdef





result.in_out_of_state_muni_interest 0.0 ne
{
  in_additions result.in_out_of_state_muni_interest add /in_additions xdef
} if

in_additions /result.in_state_additions xdef


0.0 /in_subtractions xdef






result.in_municipal_interest 0.0 ne
{
  in_subtractions result.in_municipal_interest add /in_subtractions xdef
} if

result.in_state_taxes_paid 0.0 ne
{
  in_subtractions result.in_state_taxes_paid add /in_subtractions xdef
} if

in_subtractions /result.in_state_subtractions xdef

"Indiana additions: $" result.in_state_additions cvs strconcat ", subtractions: $" strconcat result.in_state_subtractions cvs strconcat job.audit_trail swap addto
